"use client";
import * as React from "react";
import { Command as CommandPrimitive } from "cmdk";
import { Search } from "pixelarticons/react";
import { cn } from "@/lib/pixel3d";
import { nameTagClasses } from "@/components/ui/input";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { menuSeparatorClass, menuShortcutClass } from "@/components/ui/dropdown-menu";

/**
 * Command — a search name-tag on top of a list (cmdk). The highlighted item gets a lime
 * pixel block: you're choosing where to go. Use CommandDialog for a ⌘K palette.
 */
export const Command = React.forwardRef<
  React.ComponentRef<typeof CommandPrimitive>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive> & {
    /** Draw its own paper sticker. Pass false inside a Dialog / Popover sticker. */
    frame?: boolean;
  }
>(({ className, frame = true, ...props }, ref) => (
  <CommandPrimitive
    ref={ref}
    data-slot="command"
    className={cn("flex w-full flex-col gap-3 text-ink outline-none", frame && "sticker sticker-lg face-paper p-3", className)}
    {...props}
  />
));
Command.displayName = "Command";

export const CommandInput = React.forwardRef<
  React.ComponentRef<typeof CommandPrimitive.Input>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Input> & {
    /** Text for the name-tag band. Without it, the tag is plain white. */
    label?: React.ReactNode;
    wrapperClassName?: string;
  }
>(({ className, wrapperClassName, label, ...props }, ref) => (
  <div
    data-slot="command-input-wrapper"
    className={cn(nameTagClasses({ hasBand: Boolean(label), invalid: false }), wrapperClassName)}
  >
    {label && (
      <span aria-hidden className="px-3 pt-1 pb-2 text-base font-bold leading-tight">
        {label}
      </span>
    )}
    <div className="flex h-12 items-center gap-2 bg-paper px-3 text-ink">
      <Search className="pixel-icon size-6 shrink-0 text-ink-soft" aria-hidden />
      <CommandPrimitive.Input
        ref={ref}
        data-slot="command-input"
        aria-label={typeof label === "string" ? label : props["aria-label"]}
        className={cn(
          "h-full min-w-0 flex-1 bg-transparent text-lg font-medium text-ink outline-none placeholder:text-placeholder disabled:cursor-not-allowed",
          className
        )}
        {...props}
      />
    </div>
  </div>
));
CommandInput.displayName = "CommandInput";

export const CommandList = React.forwardRef<
  React.ComponentRef<typeof CommandPrimitive.List>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.List>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.List
    ref={ref}
    data-slot="command-list"
    className={cn("max-h-80 scroll-py-2 overflow-x-hidden overflow-y-auto outline-none", className)}
    {...props}
  />
));
CommandList.displayName = "CommandList";

export const CommandEmpty = React.forwardRef<
  React.ComponentRef<typeof CommandPrimitive.Empty>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Empty>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.Empty
    ref={ref}
    data-slot="command-empty"
    className={cn("py-8 text-center text-base font-medium text-ink-soft", className)}
    {...props}
  />
));
CommandEmpty.displayName = "CommandEmpty";

export const CommandGroup = React.forwardRef<
  React.ComponentRef<typeof CommandPrimitive.Group>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Group>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.Group
    ref={ref}
    data-slot="command-group"
    className={cn(
      "py-1 [&_[cmdk-group-heading]]:px-3 [&_[cmdk-group-heading]]:pt-2 [&_[cmdk-group-heading]]:pb-1 [&_[cmdk-group-heading]]:text-sm [&_[cmdk-group-heading]]:font-extrabold [&_[cmdk-group-heading]]:text-ink-soft",
      className
    )}
    {...props}
  />
));
CommandGroup.displayName = "CommandGroup";

export const CommandSeparator = React.forwardRef<
  React.ComponentRef<typeof CommandPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Separator>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.Separator
    ref={ref}
    data-slot="command-separator"
    className={cn(menuSeparatorClass, className)}
    {...props}
  />
));
CommandSeparator.displayName = "CommandSeparator";

export const CommandItem = React.forwardRef<
  React.ComponentRef<typeof CommandPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Item>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.Item
    ref={ref}
    data-slot="command-item"
    className={cn(
      "notch-fill relative flex h-11 cursor-pointer select-none items-center gap-3 px-3 text-base font-bold outline-none",
      "data-[selected=true]:[--fill:var(--color-lime)]",
      "data-[disabled=true]:pointer-events-none data-[disabled=true]:text-ink-soft/60",
      "[&_svg]:pixel-icon [&_svg]:size-5 [&_svg]:shrink-0",
      className
    )}
    {...props}
  />
));
CommandItem.displayName = "CommandItem";

export const CommandShortcut = ({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) => (
  <span data-slot="command-shortcut" className={cn(menuShortcutClass, className)} {...props} />
);
CommandShortcut.displayName = "CommandShortcut";

export interface CommandDialogProps extends React.ComponentProps<typeof Dialog> {
  /** Screen-reader title for the dialog. */
  title?: string;
  /** Screen-reader description for the dialog. */
  description?: string;
  className?: string;
  showCloseButton?: boolean;
  /** Props for the inner Command (filter, loop, value…). */
  commandProps?: React.ComponentPropsWithoutRef<typeof CommandPrimitive>;
}

export function CommandDialog({
  title = "Command palette",
  description = "Search for a page or an action",
  children,
  className,
  showCloseButton = false,
  commandProps,
  ...props
}: CommandDialogProps) {
  return (
    <Dialog {...props}>
      <DialogContent className={cn("max-w-xl", className)} bodyClassName="p-3" showCloseButton={showCloseButton}>
        <DialogHeader className="sr-only">
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>
        <Command frame={false} {...commandProps}>
          {children}
        </Command>
      </DialogContent>
    </Dialog>
  );
}
CommandDialog.displayName = "CommandDialog";

"use client";
import * as React from "react";
import { Dialog as DialogPrimitive } from "radix-ui";
import { Close } from "pixelarticons/react";
import { cn } from "@/lib/pixel3d";

/**
 * Dialog — a big paper sticker slapped onto the screen over a 45% ink overlay.
 * It drops in a little crooked and settles straight (dialog bodies never tilt);
 * closing lifts it off. The close button is a small paper sticker stuck on the corner.
 */
export const Dialog = DialogPrimitive.Root;
export const DialogTrigger = DialogPrimitive.Trigger;
export const DialogPortal = DialogPrimitive.Portal;
export const DialogClose = DialogPrimitive.Close;

export const DialogOverlay = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Overlay
    ref={ref}
    data-slot="dialog-overlay"
    className={cn("overlay-fade fixed inset-0 z-50 bg-ink/45", className)}
    {...props}
  />
));
DialogOverlay.displayName = "DialogOverlay";

export interface DialogContentProps extends React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content> {
  /** Show the corner close sticker. Default true. */
  showCloseButton?: boolean;
  /** Classes for the inner scroll body (padding, gap). The sticker itself never clips. */
  bodyClassName?: string;
}

export const DialogContent = React.forwardRef<React.ComponentRef<typeof DialogPrimitive.Content>, DialogContentProps>(
  ({ className, bodyClassName, children, showCloseButton = true, ...props }, ref) => (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Content
        ref={ref}
        data-slot="dialog-content"
        className={cn(
          "sticker sticker-lg face-paper dialog-motion fixed inset-0 z-50 m-auto flex h-fit max-h-[calc(100dvh-3rem)] w-[calc(100%-2.5rem)] max-w-lg flex-col outline-none",
          className
        )}
        {...props}
      >
        {/* scroll lives on an inner wrapper: overflow on a sticker would clip its stepped corners */}
        <div data-slot="dialog-body" className={cn("flex min-h-0 flex-col gap-6 overflow-y-auto p-7", bodyClassName)}>
          {children}
        </div>
        {showCloseButton && (
          <DialogPrimitive.Close
            data-slot="dialog-close"
            aria-label="Close"
            className="sticker face-paper peel focus-cut absolute -top-3 -right-3 grid size-11 cursor-pointer place-items-center [--p3d-tilt:2.5deg]"
          >
            <Close className="pixel-icon size-6" aria-hidden />
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPortal>
  )
);
DialogContent.displayName = "DialogContent";

export const DialogHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div data-slot="dialog-header" className={cn("flex flex-col gap-2 pr-4", className)} {...props} />
);
DialogHeader.displayName = "DialogHeader";

export const DialogFooter = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="dialog-footer"
    className={cn("flex flex-col-reverse gap-4 pt-2 sm:flex-row sm:items-center sm:justify-end", className)}
    {...props}
  />
);
DialogFooter.displayName = "DialogFooter";

export const DialogTitle = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Title>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Title
    ref={ref}
    data-slot="dialog-title"
    className={cn("text-2xl font-extrabold leading-tight tracking-[-0.02em]", className)}
    {...props}
  />
));
DialogTitle.displayName = "DialogTitle";

export const DialogDescription = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Description>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Description
    ref={ref}
    data-slot="dialog-description"
    className={cn("text-base leading-relaxed text-ink-soft", className)}
    {...props}
  />
));
DialogDescription.displayName = "DialogDescription";

"use client";
import * as React from "react";
import { DropdownMenu as DropdownMenuPrimitive } from "radix-ui";
import { Check, ChevronRight, Circle } from "pixelarticons/react";
import { cn } from "@/lib/pixel3d";

/**
 * DropdownMenu — a straight paper sticker of actions. The highlighted item gets a pink
 * pixel block (pink = do it; tomato for destructive items). Checked items land a small
 * lime check-sticker (lime = chosen). Shortcuts sit on paper key caps.
 *
 * The menu* class strings are shared by ContextMenu and Menubar.
 */
export const menuContentClass =
  "sticker sticker-lg face-paper overlay-motion z-50 flex min-w-56 flex-col p-2 text-ink outline-none";

export const menuItemClass = cn(
  "notch-fill relative flex h-10 cursor-pointer select-none items-center gap-3 px-3 text-base font-bold outline-none",
  "data-[highlighted]:[--fill:var(--color-pink)] data-[variant=destructive]:data-[highlighted]:[--fill:var(--color-tomato)]",
  "data-[disabled]:pointer-events-none data-[disabled]:cursor-not-allowed data-[disabled]:text-ink-soft/60",
  "data-[inset]:pl-10 [&_svg]:pixel-icon [&_svg]:size-5 [&_svg]:shrink-0"
);

/** checkbox / radio rows leave room on the left for the landed indicator */
export const menuChoiceItemClass = cn(menuItemClass, "pl-10");

export const menuSubTriggerClass = cn(
  menuItemClass,
  "data-[state=open]:not-data-[highlighted]:[--fill:#eef0f3]"
);

export const menuLabelClass = "px-3 pt-2 pb-1 text-sm font-extrabold text-ink-soft data-[inset]:pl-10";

export const menuSeparatorClass = "pixel-rule mx-2 my-1.5 shrink-0 text-ink/20";

/** a paper key cap with notched corners (the Kbd look); 14px is the floor for key hints */
export const menuShortcutClass =
  "notch-fill ml-auto inline-flex h-7 min-w-7 items-center justify-center px-2 text-sm font-bold tracking-normal text-ink-soft [--fill:#eef0f3]";

/** the lime mini-sticker that lands inside a checked checkbox / radio item */
export function MenuChoiceIndicator({ type }: { type: "checkbox" | "radio" }) {
  return (
    <span className="sticker face-lime animate-land grid size-6 place-items-center">
      {type === "checkbox" ? (
        <Check className="pixel-icon size-4!" aria-hidden />
      ) : (
        <Circle className="pixel-icon size-4!" aria-hidden />
      )}
    </span>
  );
}

export const DropdownMenu = DropdownMenuPrimitive.Root;
export const DropdownMenuTrigger = DropdownMenuPrimitive.Trigger;
export const DropdownMenuGroup = DropdownMenuPrimitive.Group;
export const DropdownMenuPortal = DropdownMenuPrimitive.Portal;
export const DropdownMenuSub = DropdownMenuPrimitive.Sub;
export const DropdownMenuRadioGroup = DropdownMenuPrimitive.RadioGroup;

export const DropdownMenuContent = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Content>
>(({ className, sideOffset = 12, collisionPadding = 16, ...props }, ref) => (
  <DropdownMenuPrimitive.Portal>
    <DropdownMenuPrimitive.Content
      ref={ref}
      data-slot="dropdown-menu-content"
      sideOffset={sideOffset}
      collisionPadding={collisionPadding}
      className={cn(menuContentClass, "origin-(--radix-dropdown-menu-content-transform-origin)", className)}
      {...props}
    />
  </DropdownMenuPrimitive.Portal>
));
DropdownMenuContent.displayName = "DropdownMenuContent";

export const DropdownMenuItem = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Item> & {
    inset?: boolean;
    variant?: "default" | "destructive";
  }
>(({ className, inset, variant = "default", ...props }, ref) => (
  <DropdownMenuPrimitive.Item
    ref={ref}
    data-slot="dropdown-menu-item"
    data-inset={inset || undefined}
    data-variant={variant}
    className={cn(menuItemClass, className)}
    {...props}
  />
));
DropdownMenuItem.displayName = "DropdownMenuItem";

export const DropdownMenuCheckboxItem = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.CheckboxItem>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.CheckboxItem>
>(({ className, children, ...props }, ref) => (
  <DropdownMenuPrimitive.CheckboxItem
    ref={ref}
    data-slot="dropdown-menu-checkbox-item"
    className={cn(menuChoiceItemClass, className)}
    {...props}
  >
    <span className="pointer-events-none absolute left-2 grid size-6 place-items-center">
      <DropdownMenuPrimitive.ItemIndicator>
        <MenuChoiceIndicator type="checkbox" />
      </DropdownMenuPrimitive.ItemIndicator>
    </span>
    {children}
  </DropdownMenuPrimitive.CheckboxItem>
));
DropdownMenuCheckboxItem.displayName = "DropdownMenuCheckboxItem";

export const DropdownMenuRadioItem = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.RadioItem>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.RadioItem>
>(({ className, children, ...props }, ref) => (
  <DropdownMenuPrimitive.RadioItem
    ref={ref}
    data-slot="dropdown-menu-radio-item"
    className={cn(menuChoiceItemClass, className)}
    {...props}
  >
    <span className="pointer-events-none absolute left-2 grid size-6 place-items-center">
      <DropdownMenuPrimitive.ItemIndicator>
        <MenuChoiceIndicator type="radio" />
      </DropdownMenuPrimitive.ItemIndicator>
    </span>
    {children}
  </DropdownMenuPrimitive.RadioItem>
));
DropdownMenuRadioItem.displayName = "DropdownMenuRadioItem";

export const DropdownMenuLabel = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Label>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Label> & { inset?: boolean }
>(({ className, inset, ...props }, ref) => (
  <DropdownMenuPrimitive.Label
    ref={ref}
    data-slot="dropdown-menu-label"
    data-inset={inset || undefined}
    className={cn(menuLabelClass, className)}
    {...props}
  />
));
DropdownMenuLabel.displayName = "DropdownMenuLabel";

export const DropdownMenuSeparator = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Separator>
>(({ className, ...props }, ref) => (
  <DropdownMenuPrimitive.Separator
    ref={ref}
    data-slot="dropdown-menu-separator"
    className={cn(menuSeparatorClass, className)}
    {...props}
  />
));
DropdownMenuSeparator.displayName = "DropdownMenuSeparator";

export const DropdownMenuShortcut = ({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) => (
  <span data-slot="dropdown-menu-shortcut" className={cn(menuShortcutClass, className)} {...props} />
);
DropdownMenuShortcut.displayName = "DropdownMenuShortcut";

export const DropdownMenuSubTrigger = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.SubTrigger>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.SubTrigger> & { inset?: boolean }
>(({ className, inset, children, ...props }, ref) => (
  <DropdownMenuPrimitive.SubTrigger
    ref={ref}
    data-slot="dropdown-menu-sub-trigger"
    data-inset={inset || undefined}
    className={cn(menuSubTriggerClass, className)}
    {...props}
  >
    {children}
    <ChevronRight className="ml-auto" aria-hidden />
  </DropdownMenuPrimitive.SubTrigger>
));
DropdownMenuSubTrigger.displayName = "DropdownMenuSubTrigger";

export const DropdownMenuSubContent = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.SubContent>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.SubContent>
>(({ className, sideOffset = 20, alignOffset = -8, collisionPadding = 16, ...props }, ref) => (
  <DropdownMenuPrimitive.Portal>
    <DropdownMenuPrimitive.SubContent
      ref={ref}
      data-slot="dropdown-menu-sub-content"
      sideOffset={sideOffset}
      alignOffset={alignOffset}
      collisionPadding={collisionPadding}
      className={cn(menuContentClass, "origin-(--radix-dropdown-menu-content-transform-origin)", className)}
      {...props}
    />
  </DropdownMenuPrimitive.Portal>
));
DropdownMenuSubContent.displayName = "DropdownMenuSubContent";
